package vn.cinema.service;
import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;import vn.cinema.client.NotificationClient;import java.util.Map;
@Component public class BookingJobs{private final BookingService service;private final NotificationClient notifications;public BookingJobs(BookingService s,NotificationClient n){service=s;notifications=n;}@Scheduled(fixedDelay=10000)public void expire(){for(long id:service.expired())service.expireOne(id);}@Scheduled(fixedDelay=5000)public void notifyConfirmed(){for(var b:service.unsent()){try{notifications.send(Map.of("bookingId",b.id,"userId",b.userId,"message","Vé "+b.bookingCode+" của bạn đã được xác nhận.","title","Thanh toán thành công"));service.notified(b.id);}catch(feign.FeignException e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Notification delivery will retry for booking {}",b.id);}}}}